    # Create wrapper function with prefixed name
    def make_wrapper(original_func, prefixed_name):
        def prefixed_tool(*args, **kwargs):
            return original_func(*args, **kwargs)

        prefixed_tool.__name__ = prefixed_name
        prefixed_tool.__doc__ = original_func.__doc__
        prefixed_tool.__annotations__ = original_func.__annotations__

        return prefixed_tool

    wrapped = make_wrapper(tool_func, f"math_{tool_name}")
    main_server.tool()(wrapped)

if __name__ == "__main__":
